      "causa_raiz": "Concatena\u00E7\u00E3o intensiva de strings em loop ('s += i.ToString()') e aloca\u00E7\u00E3o repetida de grandes arrays de objetos ('new object[10000]') a cada frame dentro do m\u00E9todo Update(), gerando mais de 8 MB de lixo por frame e disparando pausas graves do Garbage Collector (24.57 ms).",
      "codigo_refatorado": "using System;\\nusing System.Text;\\nusing UnityEngine;\\n\\nnamespace PerformanceAdvisor.StressTest\\n{\\n    public class StressTestScene : MonoBehaviour\\n    {\\n        public bool stressGc = false;\\n        public bool stressCpu = false;\\n        public bool stressDraw = false;\\n        public GameObject testPrefab;\\n        [Range(1, 20)] public float spawnRadius = 10f;\\n        [Range(1, 50)] public int cubesPerFrame = 1;\\n        public bool useUniqueMaterials = false;\\n        [Range(1, 512)] public int cpuScansPerFrame = 1;\\n        public int emptyObjects = 0;\\n        public int gcConcatIterations = 1000;\\n        public int gcArrayAllocs = 0;\\n        public int overdrawLayers = 0;\\n        public Material overdrawMaterial;\\n        [Range(0, 2000)] public int prepopulateCount = 0;\\n\\n        private StringBuilder _sbCached = new StringBuilder(4096);\\n        private object[][] _reusableBlocks;\\n        private static readonly int ColorPropertyId = Shader.PropertyToID(\"_Color\");\\n        private MaterialPropertyBlock _mpb;\\n\\n        private void Awake()\\n        {\\n            _mpb = new MaterialPropertyBlock();\\n            if (gcArrayAllocs > 0)\\n            {\\n                _reusableBlocks = new object[gcArrayAllocs][];\\n                for (int i = 0; i < gcArrayAllocs; i++)\\n                {\\n                    _reusableBlocks[i] = new object[10000];\\n                }\\n            }\\n        }\\n\\n        private void Start()\\n        {\\n            if (prepopulateCount > 0 && testPrefab != null)\\n            {\\n                for (int i = 0; i < prepopulateCount; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n            for (int i = 0; i < emptyObjects; i++)\\n            {\\n                new GameObject(\"Empty_\" + i);\\n            }\\n            if (overdrawLayers > 0 && overdrawMaterial != null)\\n            {\\n                BuildOverdrawLayers();\\n            }\\n        }\\n\\n        private void BuildOverdrawLayers()\\n        {\\n            Camera cam = Camera.main;\\n            if (cam == null) return;\\n            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;\\n            for (int i = 0; i < overdrawLayers; i++)\\n            {\\n                float d = cam.nearClipPlane + 0.05f + i * 0.001f;\\n                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;\\n                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\\n                Destroy(quad.GetComponent<Collider>());\\n                quad.name = \"Overdraw_\" + i;\\n                quad.transform.SetParent(cam.transform, false);\\n                quad.transform.localPosition = new Vector3(0f, 0f, d);\\n                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);\\n                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;\\n            }\\n        }\\n\\n        private void Update()\\n        {\\n            if (stressGc)\\n            {\\n                _sbCached.Clear();\\n                for (int i = 0; i < gcConcatIterations; i++)\\n                {\\n                    _sbCached.Append(i);\\n                }\\n            }\\n            if (stressDraw && testPrefab != null)\\n            {\\n                int n = Mathf.Max(1, cubesPerFrame);\\n                for (int i = 0; i < n; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n        }\\n\\n        private void SpawnOne()\\n        {\\n            var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity);\\n            if (useUniqueMaterials)\\n            {\\n                var renderer = clone.GetComponent<Renderer>();\\n                if (renderer != null)\\n                {\\n                    _mpb.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));\\n                    renderer.SetPropertyBlock(_mpb);\\n                }\\n            }\\n        }\\n    }\\n}",
      "explicacao_didatica": "Em C#, o texto ('string') n\u00E3o pode ser modificado ap\u00F3s criado. Quando voc\u00EA usa '+=' dentro de um loop, a Unity cria uma nova string na mem\u00F3ria a cada repeti\u00E7\u00E3o e descarta a anterior. Isso enche a mem\u00F3ria RAM com lixo, fazendo o Garbage Collector (GC) pausar o jogo para limpar tudo, gerando travamentos ('stutters'). Usar 'StringBuilder' ou evitar aloca\u00E7\u00F5es tempor\u00E1rias dentro do Update reaproveita a mem\u00F3ria existente sem gerar lixo."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Execu\u00E7\u00E3o de 'GameObject.FindObjectsOfType<GameObject>()' repetidamente a cada frame dentro do m\u00E9todo Update(), o que for\u00E7a uma varredura completa da \u00E1rvore de objetos em mem\u00F3ria nativa e aloca um array novo a cada chamada, elevando o tempo de processador para at\u00E9 380 ms.",
      "codigo_refatorado": "using UnityEngine;\\n\\nnamespace PerformanceAdvisor.StressTest\\n{\\n    public class CpuStressRefactored : MonoBehaviour\\n    {\\n        [SerializeField] private Transform[] trackedTransforms;\\n\\n        private void Awake()\\n        {\\n            CacheSceneReferences();\\n        }\\n\\n        public void CacheSceneReferences()\\n        {\\n            var allGos = FindObjectsOfType<GameObject>();\\n            trackedTransforms = new Transform[allGos.Length];\\n            for (int i = 0; i < allGos.Length; i++)\\n            {\\n                trackedTransforms[i] = allGos[i].transform;\\n            }\\n        }\\n\\n        private void Update()\\n        {\\n            if (trackedTransforms == null) return;\\n            for (int i = 0; i < trackedTransforms.Length; i++)\\n            {\\n                if (trackedTransforms[i] != null)\\n                {\\n                    _ = trackedTransforms[i].position;\\n                }\\n            }\\n        }\\n    }\\n}",
      "explicacao_didatica": "A fun\u00E7\u00E3o 'FindObjectsOfType' \u00E9 muito pesada porque precisa revirar toda a cena do jogo procurando objeto por objeto. Fazer isso 60 vezes por segundo dentro do Update() sobrecarrega o processador (CPU), causando quedas bruscas de FPS. O ideal \u00E9 buscar ou armazenar refer\u00E9ncias apenas no in\u00EDcio (Awake/Start) e apenas reaproveitar essas refer\u00E9ncias durante o jogo."
    }
  ],
